<div class="card form-card"><form method="post" action="?page=projects&action=<?=$mode==='create'?'store':'update&id='.$project['id']?>"><?=$csrfField?><div class="form-grid"><label>Nama Project<input name="name" required value="<?=e($project['name'])?>"><?php if(isset($errors['name'])):?><small class="field-error"><?=e($errors['name'])?></small><?php endif;?></label><label>Status<select name="status"><?php foreach(['Planning','Active','Completed','Archived'] as $s):?><option <?=($project['status']===$s?'selected':'')?> value="<?=$s?>"><?=$s?></option><?php endforeach;?></select><?php if(isset($errors['status'])):?><small class="field-error"><?=e($errors['status'])?></small><?php endif;?></label><label>Start Date<input type="date" name="start_date" required value="<?=e($project['start_date'])?>"></label><label>Target Date<input type="date" name="target_date" required value="<?=e($project['target_date'])?>"><?php if(isset($errors['target_date'])):?><small class="field-error"><?=e($errors['target_date'])?></small><?php endif;?></label><label class="full-field">Description<textarea name="description" required rows="5"><?=e($project['description'])?></textarea></label></div><div class="form-actions"><a class="btn" href="?page=projects">Cancel</a><button class="btn btn-primary">Save</button></div></form></div>
